def variant_of(method):
    """方法名的前缀只控制权限，后缀才是小修编号。"""
    return method.split('__', 1)[-1] if '__' in method else 'M0_BASE'


def task_for(environment, k, control, variant, seed, stage='MAIN', block=0):
    if environment == 'E0' and control != 'LQ':
        raise ValueError('E0不存在真实飞机控制，不生成伪联合格')
    method = ('J3' if control == 'J3' else 'SINGLE') + '__' + variant
    return dict(id=f'{stage}__{environment}__K{k}__{method}__s{seed}', environment=environment,
                k=k, fleet=12 if environment == 'E1' else None, control=control,
                method=method, variant=variant, seed=seed, stage=stage, block=block)


def min_registry():
    """前96run优先回答E1的单/联合问题；区组内轮换而不是结果驱动排序。"""
    priority = [('E1', k, c, s) for k in (2, 4) for c in ('LQ', 'J3') for s in SEEDS[:3]]
    priority += [('E0', k, 'LQ', s) for k in (2, 4) for s in SEEDS[:2]]
    all_blocks = [(e, k, c, s) for e, c in (('E0', 'LQ'), ('E1', 'LQ'), ('E1', 'J3'))
                  for k in (2, 3, 4) for s in SEEDS]
    blocks = priority + [b for b in all_blocks if b not in priority]
    tasks = []
    for b, (e, k, c, s) in enumerate(blocks):
        variants = VARIANTS[b % 6:] + VARIANTS[:b % 6]
        tasks.extend(task_for(e, k, c, v, s, block=b) for v in variants)
    assert len(tasks) == 216 and len({t['id'] for t in tasks}) == 216
    assert len(tasks[:96]) * STEPS == 96_337_920
    return tasks


class MinimalSchema:
    """策略只读源六帧；权限标志不进入LSTM，不增加事件网络。"""
    def __init__(self, k):
        self.k = int(k)
        self.frame = 4 + 8 * self.k
        self.history = 6 * self.frame
        self.passenger_active = self.history
        self.pack = self.history + 1
        self.return_mask = slice(2 * self.pack, 2 * self.pack + self.k)
        self.dim = 2 * self.pack + self.k

    def manifest(self):
        return dict(k=self.k, frame=self.frame, history=self.history, pack=self.pack, dim=self.dim,
                    observation='源六帧；每站第7个字段供M1/M2复用；权限标志不入神经编码器',
                    contract='乘客/critic只读前态；飞机actor仅在真实dispatch点读取后态')


def ready_descriptor(scenario, vid):
    """已承诺空机的保守分钟描述符，不是未知未来的预测或完整队列等待时间。

    只纳入本站空闲/充电、已经飞向本站的空机；不假设目的站尚未分配的返航目标。
    ceil飞行＋ceil充电沿用历史编码的离散近似，源分钟先后顺序可带来一tick误差。
    无已承诺供给用601，显式保留哨兵，不能称作实际需要等601分钟。
    """
    from at_obj.vertiport.vertiport_spec import VERTIPORT_CHARGE_RATE
    supply = []
    for plane in scenario._all_evtols.values():
        if plane.passenger_ids:
            continue
        state = plane.state.name
        here = str(plane.current_vertiport_id) == str(vid) and state != 'FLYING'
        arriving = state == 'FLYING' and str(plane.target_vertiport_id) == str(vid)
        if state == 'IDLE' and here:
            supply.append(0.)
        elif (state == 'CHARGING' and here) or arriving:
            rate = float(VERTIPORT_CHARGE_RATE[str(vid)]) if arriving else float(plane.spec.charge_rate_kwh_per_min)
            charge = math.ceil(max(0., plane.spec.battery_capacity_kwh - plane.battery_kwh) / max(rate, 1e-8))
            flight = math.ceil(max(0., float(plane.remaining_time))) if arriving else 0
            supply.append(float(charge + flight))
    return min(supply) if supply else 601.


def min_initialize():
    """保留物理类和PPO采样流程；仅替换小维输入、编码器及可审计的辅助更新。"""
    global MIN_RUNTIME_PID, FullSchema, FullEnv, FullFeatures, FullPPO, FullVecNormalize, FullPolicy
    if MIN_RUNTIME_PID == os.getpid():
        return
    _legacy_initialize()
    OldEnv, OldPolicy, OldPPO = FullEnv, FullPolicy, FullPPO
    from torch import nn
    import torch.nn.functional as F
    from stable_baselines3.common.torch_layers import BaseFeaturesExtractor
    from stable_baselines3.common.vec_env import VecNormalize
    from stable_baselines3 import PPO

    class MinEnv(OldEnv):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.variant = variant_of(self.method)
            self._ready_counts = [0, 0]
            if self.variant in ('M1_READY', 'M2_EFFECT_SLACK'):
                original_encode = self.raw.encoder.encode
                def encode(scenario, state):
                    frame = np.asarray(original_encode(scenario, state), np.float32).copy()
                    # 每帧以本帧OD和本帧状态计算，绝不倒改历史帧的时间原点。
                    for i, vid in enumerate(CANDIDATES[self.k]):
                        ready = ready_descriptor(scenario, vid)
                        self._ready_counts[0] += 1
                        self._ready_counts[1] += int(ready == 601.)
                        diagnostics = self.control_stats.setdefault('readiness_descriptor',
                            dict(observations=0, no_committed_supply=0, idle_now=0, positive_eta=0))
                        diagnostics['observations'] += 1
                        diagnostics['no_committed_supply'] += int(ready == 601.)
                        diagnostics['idle_now'] += int(ready == 0.)
                        diagnostics['positive_eta'] += int(0. < ready < 601.)
                        if self.variant == 'M2_EFFECT_SLACK' and bool(state['waiting_decisions']) and ready != 601.:
                            person = scenario.persons.persons[state['waiting_decisions'][0]]
                            access = float(scenario.vehicles.estimate_travel_time(person.origin_position,
                                           scenario.vertiports.vertiport_list[str(vid)].vertiport_position))
                            ready -= access
                        frame[4 + 8 * i + 6] = ready
                    return frame
                self.raw.encoder.encode = encode

        def _events_and_pack(self, history, focal=None):
            # 不扫描364个事件槽，不加入独立OD分支，不对M0重写源观测。
            frame_history = np.asarray(history, dtype=np.float32).reshape(-1).copy()
            if variant_of(self.method) == 'M2_EFFECT_SLACK' and self._generator is not None:
                # 飞机头保持M1的原分钟坐标，只让乘客/critic使用生效时间差；
                # 反变换使用每一历史帧自己的OD，不能拿当前OD重写过去。
                frames = frame_history.reshape(6, self.schema.frame)
                for frame in frames:
                    if not np.any(frame[:4]):
                        continue
                    for i, vid in enumerate(CANDIDATES[self.k]):
                        index = 4 + 8 * i + 6
                        if frame[index] != 601.:
                            frame[index] += float(self.scenario.vehicles.estimate_travel_time(
                                frame[:2], self.scenario.vertiports.vertiport_list[str(vid)].vertiport_position))
            active = bool(self.scenario.waiting_decisions)
            return np.concatenate([frame_history, np.asarray([float(active)], np.float32)])

        def counterfactual_pre(self, od):
            # 本轮不再沿用旧输入打乱探针，以免把M2的派生字段改得物理不一致。
            return self.current.copy()

    class MinNormalize(VecNormalize):
        def normalize_obs(self, obs):
            value = super().normalize_obs(obs)
            schema = getattr(self, '_full_schema', None)
            if schema is None:
                schema = MinimalSchema(int(self.venv.get_attr('k', indices=[0])[0]))
                self._full_schema = schema
            for start in (0, schema.pack):
                value[..., start + schema.passenger_active] = np.asarray(obs)[..., start + schema.passenger_active]
            value[..., schema.return_mask] = np.asarray(obs)[..., schema.return_mask]
            return value.astype(np.float32)

    class MinFeatures(BaseFeaturesExtractor):
        def __init__(self, observation_space, k=2, method='SINGLE__M0_BASE', environment='E0'):
            super().__init__(observation_space, 128)
            from utilss.encoding import TemporalLSTMExtractor
            self.k, self.method, self.environment = k, method, environment
            self.variant = variant_of(method)
            self.schema = d = MinimalSchema(k)
            self.temporal = TemporalLSTMExtractor(gym.spaces.Box(-np.inf, np.inf, (6, d.frame), np.float32), features_dim=128)
            # 辅助头不消耗策略初始化随机序列，不出现在任何推理数据通路中。
            with torch.random.fork_rng(devices=[]):
                torch.random.default_generator.manual_seed(731_947 + k)
                if self.variant in ('M3_INVERSE', 'M4_PROJECTED', 'C4_NORM_SHAM', 'C3_SHUFFLED'):
                    self.aux_head = nn.Sequential(nn.Linear(256, 64), nn.Tanh(), nn.Linear(64, 2 * k))
                elif self.variant in ('M5_VALUE_AUX', 'C5_LATENT_MSE'):
                    self.aux_head = nn.Sequential(nn.Linear(128 + 2 * k, 64), nn.Tanh(), nn.Linear(64, 128))

        def forward(self, obs):
            return self.temporal(obs[:, :self.schema.history].reshape(-1, 6, self.schema.frame))

        def dispatch_features(self, obs):
            d = self.schema
            return self.temporal(obs[:, d.pack:d.pack + d.history].reshape(-1, 6, d.frame))

        def auxiliary_parameters(self):
            return list(self.aux_head.parameters()) if hasattr(self, 'aux_head') else []

    class MinPolicy(OldPolicy):
        def _build(self, lr_schedule):
            # 源ActorCriticPolicy会遍历全部特征模块做正交初始化；先暂存aux才能保证
            # M0/M3/M4/M5的源策略初始权重逐位一致，不能仅保护构造器的一次随机数。
            features = self.features_extractor
            auxiliary = features._modules.pop('aux_head', None)
            try:
                super()._build(lr_schedule)
            finally:
                if auxiliary is not None:
                    features.add_module('aux_head', auxiliary)

        def return_distribution(self, obs, passenger):
            d = self.features_extractor.schema
            legal = obs[:, d.return_mask] > .5
            # 全批次只有唯一合法动作时，跳过无意义的第二次LSTM；概率和梯度严格等价。
            if bool((legal.sum(-1) == 1).all()):
                logits = torch.zeros_like(obs[:, d.return_mask]).masked_fill(~legal, -1e9)
                return torch.distributions.Categorical(logits=logits)
            return super().return_distribution(obs, passenger)

    class MinPPO(OldPPO):
        def collect_rollouts(self, *args, **kwargs):
            started = time.perf_counter()
            vector = args[0].venv if args else kwargs['env'].venv
            original_method = vector.env_method
            totals = defaultdict(float)
            def timed(method_name, *a, **kw):
                begin = time.perf_counter()
                try:
                    return original_method(method_name, *a, **kw)
                finally:
                    totals[method_name] += time.perf_counter() - begin
            vector.env_method = timed
            try:
                result = super().collect_rollouts(*args, **kwargs)
            finally:
                vector.env_method = original_method
            self._min_sampling_seconds = time.perf_counter() - started
            self._min_rpc = dict(totals)
            return result

        def _excluded_save_params(self):
            return super()._excluded_save_params() + ['_min_aux_batch', '_min_frozen_value']

        def _auxiliary(self, batch, value_head):
            features = self.policy.features_extractor
            x, y, action, active_p, active_r = batch
            h = features(x)
            hn = features(y)
            v = features.variant
            if v in ('M3_INVERSE', 'M4_PROJECTED', 'C4_NORM_SHAM', 'C3_SHUFFLED'):
                pred = features.aux_head(torch.cat([h, hn], -1)).reshape(-1, 2, features.k)
                labels = torch.stack([action // features.k, action % features.k], -1)
                losses = []
                accuracies = []
                for role, valid in enumerate((active_p, active_r)):
                    if bool(valid.any()):
                        truth = labels[valid, role]
                        if v == 'C3_SHUFFLED':
                            truth = truth.roll(1, 0)
                        losses.append(F.cross_entropy(pred[valid, role], truth))
                        accuracies.append(float((pred[valid, role].argmax(-1) == truth).float().mean().detach()))
                self._min_aux_quality = dict(inverse_accuracy=mean(accuracies) if accuracies else 0.)
                return torch.stack(losses).mean() if losses else h.sum() * 0.
            ids = torch.cat([F.one_hot(action // features.k, features.k),
                             F.one_hot(action % features.k, features.k)], -1).to(h.dtype)
            prediction = features.aux_head(torch.cat([h, ids], -1))
            if v == 'C5_LATENT_MSE':
                self._min_aux_quality = dict(latent_target_variance=float(hn.detach().var(unbiased=False)))
                return F.mse_loss(prediction, hn.detach())
            # 冻结的源critic读出保证target与预测在本次更新内同坐标；不向策略喂未来真值。
            target = value_head(hn.detach()).detach()
            self._min_aux_quality = dict(value_target_variance=float(target.var(unbiased=False)))
            return F.mse_loss(value_head(prediction), target)

        def train(self):
            if self.device.type == 'cuda':
                torch.cuda.synchronize(self.device)
            started = time.perf_counter()
            features = self.policy.features_extractor
            enabled = hasattr(features, 'aux_head')
            batch = None
            if enabled:
                rb = self.rollout_buffer
                valid = np.argwhere(~rb.episode_starts[1:].astype(bool))
                # 私有采样器不改变PPO的numpy打乱顺序；相邻transition不跨episode。
                rng = np.random.default_rng(int(self.seed or 0) * 1000003 + self.num_timesteps)
                if len(valid):
                    rows = valid[rng.choice(len(valid), min(AUX_SAMPLES, len(valid)), replace=False)]
                    t, e = rows[:, 0], rows[:, 1]
                    x = torch.as_tensor(rb.observations[t, e].copy(), device=self.device)
                    y = torch.as_tensor(rb.observations[t + 1, e].copy(), device=self.device)
                    action = torch.as_tensor(rb.actions[t, e].reshape(-1).copy(), device=self.device).long()
                    d = features.schema
                    batch = (x, y, action, x[:, d.passenger_active] > .5,
                             (x[:, d.return_mask] > .5).sum(-1) > 1)
            shared = list(features.temporal.parameters())
            heads = features.auxiliary_parameters()
            expected = self.n_epochs * math.ceil(self.n_steps * self.n_envs / self.batch_size)
            per_epoch = math.ceil(self.n_steps * self.n_envs / self.batch_size)
            calls, stats, observations = 0, {}, []
            original_clip = torch.nn.utils.clip_grad_norm_
            # 所有小修拥有相同PPO优化器步数；aux只注入各epoch最后一次原有更新。
            frozen = None
            if batch is not None and features.variant in ('M5_VALUE_AUX', 'C5_LATENT_MSE'):
                frozen = copy.deepcopy(nn.Sequential(self.policy.mlp_extractor.value_net, self.policy.value_net)).to(self.device)
                frozen.eval()
                for p in frozen.parameters():
                    p.requires_grad_(False)
            def clip_hook(parameters, max_norm, *a, **kw):
                nonlocal calls
                calls += 1
                if calls % per_epoch == 0 and batch is not None:
                    loss = self._auxiliary(batch, frozen)
                    gradients = torch.autograd.grad(loss, shared + heads, allow_unused=True)
                    g = torch.cat([(p.grad if p.grad is not None else torch.zeros_like(p)).detach().flatten() for p in shared])
                    u = torch.cat([(v if v is not None else torch.zeros_like(p)).detach().flatten() for p, v in zip(shared, gradients)])
                    gnorm, unorm = g.norm(), u.norm()
                    dot = torch.dot(g, u)
                    cosine = dot / (gnorm * unorm + 1e-12)
                    projected = u - torch.minimum(dot, dot.new_zeros(())) / (g.square().sum() + 1e-12) * g
                    if features.variant == 'M4_PROJECTED':
                        u = projected
                    elif features.variant == 'C4_NORM_SHAM':
                        u = u * projected.norm() / (unorm + 1e-12)
                    # 公共上限不放大微小梯度，PPO共享梯度为零时关闭aux干预。
                    u = u * torch.clamp(AUX_RATIO * gnorm / (u.norm() + 1e-12), max=1.)
                    offset = 0
                    for p in shared:
                        extra = u[offset:offset + p.numel()].reshape_as(p)
                        p.grad = extra.clone() if p.grad is None else p.grad.add_(extra)
                        offset += p.numel()
                    self.aux_optimizer.zero_grad(set_to_none=True)
                    for p, grad in zip(heads, gradients[len(shared):]):
                        p.grad = None if grad is None else grad.detach().clone()
                    for group in self.aux_optimizer.param_groups:
                        group['lr'] = self.lr_schedule(self._current_progress_remaining)
                    original_clip(heads, self.max_grad_norm)
                    self.aux_optimizer.step()
                    # 辅助头绝不被PPO再更新一次，也不挤占PPO的全局裁剪范数。
                    for p in heads:
                        p.grad = None
                    stats.update(aux_loss=float(loss.detach()), gradient_cosine=float(cosine),
                                 ppo_shared_norm=float(gnorm), aux_original_norm=float(unorm),
                                 aux_applied_norm=float(u.norm()), projected=int(float(dot) < 0.))
                    stats.update(getattr(self, '_min_aux_quality', {}))
                    observations.append(dict(stats))
                return original_clip(parameters, max_norm, *a, **kw)
            torch.nn.utils.clip_grad_norm_ = clip_hook
            try:
                PPO.train(self)
            finally:
                torch.nn.utils.clip_grad_norm_ = original_clip
            if calls != expected:
                raise RuntimeError(f'原PPO更新次数改变：{calls}，预期{expected}；拒绝静默改变训练合同')
            if self.device.type == 'cuda':
                torch.cuda.synchronize(self.device)
            row = dict(step=self.num_timesteps, sampling_seconds=getattr(self, '_min_sampling_seconds', 0.),
                       update_seconds=time.perf_counter() - started, ppo_minibatches=calls,
                       aux_pairs=len(batch[0]) if batch is not None else 0,
                       aux_injections=len(observations), **stats)
            rpc = getattr(self, '_min_rpc', {})
            row.update(prepare_rpc_seconds=rpc.get('prepare_step', 0.), finish_rpc_seconds=rpc.get('finish_step', 0.),
                       reset_rpc_seconds=rpc.get('reset_selected', 0.))
            if observations:
                row['gradient_cosine_mean'] = mean([r['gradient_cosine'] for r in observations])
                row['negative_cosine_fraction'] = mean([r['projected'] for r in observations])
                row['aux_loss_mean'] = mean([r['aux_loss'] for r in observations])
            for key, value in row.items():
                self.logger.record('diagnosis/' + key, value)
            history = getattr(self, '_min_timing', [])
            history.append(row); self._min_timing = history
            if self._full_save_hook is not None:
                self._full_save_hook(self)

    for cls in (MinEnv, MinNormalize, MinFeatures, MinPolicy, MinPPO):
        cls.__qualname__ = cls.__name__
        cls.__module__ = __name__
        globals()[cls.__name__] = cls
    FullSchema, FullEnv, FullVecNormalize = MinimalSchema, MinEnv, MinNormalize
    FullFeatures, FullPolicy, FullPPO = MinFeatures, MinPolicy, MinPPO
    MIN_RUNTIME_PID = os.getpid()


# 工厂和历史训练函数通过此全局入口取得新的小修实现，不运行旧大网络。
initialize_full_runtime = min_initialize


def min_train(task, root, config):
    # 沿用源训练/恢复流程，但manifest必须如实标明本轮小修而非旧EventGraph。
    global full_resume_hook
    original = full_resume_hook
    directory = Path(root) / 'cells' / task['id']
    pointer = read_json(directory / 'RESUME_POINTER.json', {}) if config['resume'] else {}
    initial_step = pointer.get('step', 0)
    measured, uncertain = budget_account(root)
    if measured + uncertain + max(0, STEPS-initial_step) > HARD_CAP:
        raise RuntimeError('包含失败尝试及未落盘尾段的预算上界将超过240M，保留本格而不继续烧算力')
    attempt = directory / 'attempts' / (str(time.time_ns()) + '.json')
    previous_segments = set((directory / 'training').glob('segment_*'))
    save_json(attempt, dict(start_step=initial_step, status='RUNNING', time=now()))
    def wrapped(directory):
        previous = original(directory)
        def hook(model):
            start = time.perf_counter(); previous(model)
            save_json(attempt, dict(start_step=initial_step, last_logged_step=model.num_timesteps,
                      measured_transitions=max(0, model.num_timesteps-initial_step),
                      unlogged_tail_upper_bound=20480, status='RUNNING', time=now()))
            rows = getattr(model, '_min_timing', [])
            if rows:
                rows[-1]['resume_save_seconds'] = time.perf_counter() - start
                save_csv(Path(directory) / 'TIMING_GRADIENT.csv', rows)
            manifest = read_json(Path(directory) / 'MODEL_MANIFEST.json', {})
            manifest.update(variant=task['variant'], auxiliary=task['variant'],
                            architecture='源TemporalLSTM128＋源pi/vf256×256；仅Joint增加相同条件飞机头',
                            auxiliary_budget='每rollout至多512相邻对，各epoch最后一次原有PPO更新，共享梯度上限0.1',
                            runtime_sha256=_RUNTIME_SHA, inference_auxiliary=False)
            save_json(Path(directory) / 'MODEL_MANIFEST.json', manifest)
        return hook
    full_resume_hook = wrapped
    try:
        _legacy_train(task, root, config)
    finally:
        full_resume_hook = original
        maximum = initial_step
        for segment in set((directory / 'training').glob('segment_*')) - previous_segments:
            path = segment / 'progress.csv'
            if path.exists():
                with path.open(encoding='utf-8', errors='replace') as stream:
                    for row in csv.DictReader(stream):
                        value = row.get('time/total_timesteps')
                        if value:
                            maximum = max(maximum, int(float(value)))
        save_json(attempt, dict(start_step=initial_step, last_logged_step=maximum,
                  measured_transitions=max(0, maximum-initial_step),
                  unlogged_tail_upper_bound=20480, status='FINISHED' if (directory/'TRAIN_END.json').exists() else 'INTERRUPTED', time=now()))


def budget_account(root):
    """记录真实已测工作与中断尾段上界；失败尝试不能从预算账本中抹掉。"""
    measured = uncertain = 0
    for file in Path(root).glob('cells/*/attempts/*.json'):
        item = read_json(file, {})
        measured += item.get('measured_transitions', 0)
        if item.get('status') != 'FINISHED':
            uncertain += item.get('unlogged_tail_upper_bound', 20480)
    return measured, uncertain


def min_replay(model, norm, root, task, config, seed, deterministic=True, rule=None, probe=False):
    # 旧反事实OD输入探针对M2不适用，禁用；不改物理时限以等待尾批完成。
    return _legacy_replay(model, norm, root, task, config, seed, deterministic, rule, False)


full_replay = min_replay


def min_eval(task, root, config):
    _legacy_eval(task, root, config)
    directory = Path(root) / 'cells' / task['id']
    try:
        result = read_json(directory / 'CELL_SUMMARY.json')
        points = [read_json(p)['summary'] for p in (directory / 'evaluation').glob('step_*.json')]
        points = sorted((r for r in points if r.get('DET_co') is not None), key=lambda r:r['step'])
        if not points:
            raise RuntimeError('没有可用的完成者ATT，不填伪值')
        best = min(points, key=lambda r:r['DET_co'])
        result.update(best_step=best['step'], best_completion=best['DET_completion'], best_rpt=best['DET_rpt'],
                      metric_scope='同一训练需求trace的回放，不是held-out需求泛化；DET选择Best，STO补充',
                      eligibility='Best完成率下降≤0.5个百分点且RPT恶化≤2%，再讨论ATT增量')
        save_json(directory / 'CELL_SUMMARY.json', result)
    except Exception:
        # 仅移除本worker刚写的成功标志，原评估文件和错误证据全部保留供重试。
        (directory / 'EVAL_END.json').unlink(missing_ok=True)
        raise


def min_aggregate(root, tasks):
    rows, status, groups, rules = [], [], [], []
    for t in tasks:
        p = Path(root) / 'cells' / t['id']
        train, result = read_json(p / 'TRAIN_END.json'), read_json(p / 'CELL_SUMMARY.json')
        if result and result.get('best_completion') is None:
            result = None
        failed = any('_RESOLVED_' not in f.name for f in p.glob('FAILED_*.json'))
        live = read_json(p / 'LIVE.json', {})
        status.append(dict(**t, trained=bool(train), evaluated=bool(result), failed=failed,
                           steps=train['steps'] if train else live.get('steps', 0)))
        if result:
            for mode in ('DET', 'STO'):
                rows.append(dict(**t, mode=mode, **result[mode], best_step=result.get('best_step'),
                                 best_completion=result.get('best_completion'), best_rpt=result.get('best_rpt')))
    for e in ('E0', 'E1'):
        for k in (2, 3, 4):
            record = read_json(Path(root) / 'cells' / f'RULES__{e}__K{k}' / 'RULES_END.json')
            if not record:
                continue
            for rule in FULL_RULES:
                items = [r for r in record['episodes'] if r['mode'] == rule]
                if items:
                    rules.append(dict(environment=e, k=k, rule=rule, co=mean([r['ATT_completed_only'] for r in items]),
                                      completion=mean([r['completion'] for r in items]),
                                      rpt=mean([r['restricted_person_time_per_generated'] for r in items]),
                                      control='J3' if rule == 'READY_QUEUE_JOINT' else 'LQ'))
    keys = sorted({(r['stage'], r['environment'], r['k'], r['control'], r['variant'], r['mode']) for r in rows})
    paired = []
    for stage, e, k, c, v, mode in keys:
        items = [r for r in rows if (r['stage'], r['environment'], r['k'], r['control'], r['variant'], r['mode']) == (stage, e, k, c, v, mode)]
        group = dict(stage=stage, environment=e, k=k, control=c, variant=v, mode=mode, n=len(items),
                     best_att=mean([r['best_co'] for r in items]), best_sd=sd([r['best_co'] for r in items]),
                     plateau=mean([r['late_co'] for r in items]), plateau_sd=sd([r['late_co'] for r in items]),
                     within_run_sd=mean([r['late_sd'] for r in items]), completion=mean([r['completion'] for r in items]))
        reference = [r for r in rules if r['environment'] == e and r['k'] == k and (c == 'J3' or r['control'] == 'LQ')]
        if reference:
            strongest = min(reference, key=lambda r:r['co'])
            group.update(rule=strongest['rule'], rule_att=strongest['co'], difference_to_rule=group['best_att'] - strongest['co'],
                         rule_scope='同场景已测在线规则的后验envelope；不是数学下界')
        groups.append(group)
        for r in items:
            base = next((b for b in rows if b['stage'] == stage and b['environment'] == e and b['k'] == k and
                         b['control'] == c and b['seed'] == r['seed'] and b['variant'] == 'M0_BASE' and b['mode'] == mode), None)
            if base:
                paired.append(dict(stage=stage, environment=e, k=k, control=c, variant=v, seed=r['seed'], mode=mode,
                                   delta_best=r['best_co'] - base['best_co'], delta_plateau=r['late_co'] - base['late_co'],
                                   completion_delta=r['best_completion'] - base['best_completion'],
                                   rpt_delta=r['best_rpt'] - base['best_rpt'],
                                   eligible=r['best_completion'] >= base['best_completion'] - .005
                                            and r['best_rpt'] <= base['best_rpt'] * 1.02))
    save_csv(Path(root) / 'RUN_STATUS.csv', status)
    save_csv(Path(root) / 'METHOD_SEED_RESULTS.csv', rows)
    save_csv(Path(root) / 'GROUP_RESULTS.csv', groups)
    save_csv(Path(root) / 'PAIRED_RESULTS.csv', paired)
    save_csv(Path(root) / 'RULE_RESULTS.csv', rules)
    progress = dict(total=234, registered=len(tasks), main_total=216, confirmation_total=18,
                    trained=sum(r['trained'] for r in status), evaluated=sum(r['evaluated'] for r in status),
                    failed=sum(r['failed'] for r in status), completed_training_transitions=sum(r['steps'] for r in status if r['trained']),
                    planned_actual_budget=TOTAL_BUDGET, budget_cap=HARD_CAP, time=now())
    measured, uncertain = budget_account(root)
    progress.update(measured_training_work=measured, interrupted_unlogged_upper_bound=uncertain)
    save_json(Path(root) / 'progress.json', progress)
    return progress, rows, paired


def choose_confirmation(root, tasks):
    """完整主矩阵之后才锁定候选；独立新seed不参与候选选择。"""
    old = read_json(Path(root) / 'CONFIRMATION_SELECTION.json')
    if old:
        return old['tasks']
    _, rows, paired = min_aggregate(root, tasks)
    scores = []
    for variant in VARIANTS[1:]:
        items = [r for r in paired if r['stage'] == 'MAIN' and r['environment'] == 'E1' and r['k'] == 4
                 and r['variant'] == variant and r['mode'] == 'DET']
        # 任何核心seed缺失或完成率下降，都不能把其较低CO-ATT用于晋级。
        if len(items) == 8 and all(r['eligible'] for r in items):
            scores.append((mean([r['delta_best'] for r in items]), variant))
    improving = sorted((s, v) for s, v in scores if s < 0.)
    chosen = improving[0][1] if improving else 'M2_EFFECT_SLACK'
    contrast = dict(M1_READY='M2_EFFECT_SLACK', M2_EFFECT_SLACK='M1_READY', M3_INVERSE='C3_SHUFFLED',
                    M4_PROJECTED='C4_NORM_SHAM', M5_VALUE_AUX='C5_LATENT_MSE')[chosen]
    confirm = [task_for('E1', 4, c, v, s, 'CONFIRM', b)
               for b, (c, s) in enumerate((c, s) for c in ('LQ', 'J3') for s in FRESH_SEEDS)
               for v in ('M0_BASE', chosen, contrast)]
    assert len(confirm) == 18 and (len(tasks)+len(confirm))*STEPS == TOTAL_BUDGET
    save_json(Path(root) / 'CONFIRMATION_SELECTION.json', dict(chosen=chosen, contrast=contrast, scores=scores,
              reason='完整E1K4八配对均满足完成率下降≤0.5个百分点、RPT恶化≤2%后按平均Best差选择；无改善则预注册M2否证复核，不宣布胜者',
              independent_demand=False, independent_training_seeds=True, tasks=confirm, time=now()))
    return confirm


def min_main():
    parser = argparse.ArgumentParser(description='UAGMC五个小修：234.82368M实际步；原物理只读；可续训、失败隔离')
    parser.add_argument('--root'); parser.add_argument('--resume', action='store_true')
    parser.add_argument('--retry-failed', action='store_true'); parser.add_argument('--allow-code-change', action='store_true')
    parser.add_argument('--phase', choices=('all', 'train', 'eval', 'rules', 'pack'), default='all')
    parser.add_argument('--device', default='cuda'); parser.add_argument('--eval-device', default='cpu')
    parser.add_argument('--timeout-hours', type=float, default=3.)
    parser.add_argument('--worker', choices=('train', 'eval', 'rules')); parser.add_argument('--task')
    parser.add_argument('--list', action='store_true')
    args = parser.parse_args()
    if args.worker:
        record = read_json(args.task)
        try:
            dict(train=min_train, eval=min_eval, rules=_legacy_rules)[args.worker](record['task'], Path(args.root).resolve(), record['config'])
        except KeyboardInterrupt:
            raise SystemExit(130)
        except Exception:
            traceback.print_exc(); raise SystemExit(1)
        return
    tasks = min_registry()
    if args.list:
        print(json.dumps(dict(version=MIN_VERSION, main_runs=len(tasks), confirmation_runs=18,
              main_steps=MAIN_BUDGET, total_steps=TOTAL_BUDGET, remaining_to_240m=HARD_CAP-TOTAL_BUDGET,
              variants=VARIANTS, tasks=tasks, ppo=SOURCE_PPO), ensure_ascii=False, indent=2))
        return
    root = Path(args.root).resolve() if args.root else SCRIPT.parent / 'serial_runs' / MIN_ROOT
    if args.phase == 'pack':
        if not (root / 'SUITE_PLAN.json').is_file():
            raise FileNotFoundError('不是本轮结果目录')
        full_pack(root); return
    if args.timeout_hours <= 0:
        parser.error('timeout-hours必须大于0')
    if args.phase in ('all', 'train') and args.device.startswith('cuda') and not os.environ.get('CUDA_VISIBLE_DEVICES'):
        raise RuntimeError('请由用户先查看top/nvidia-smi，并显式指定CUDA_VISIBLE_DEVICES')
    if root.exists() and any(root.iterdir()) and not args.resume:
        raise FileExistsError('已有记录请使用--resume，不覆盖原始结果')
    root.mkdir(parents=True, exist_ok=True)
    lock = strict_lock(root)
    try:
        native = materialize_source(root)
        config = dict(version=MIN_VERSION, device=args.device, eval_device=args.eval_device,
                      trace=str(native / 'train_data' / 'passengers_300.csv'), train_horizon=500, eval_horizon=600,
                      actual_steps=STEPS, requested_steps=1_000_000, resume=args.resume,
                      retry_failed=args.retry_failed, timeout_hours=args.timeout_hours)
        contract = dict(version=MIN_VERSION, variants=VARIANTS, seeds=SEEDS, confirmation_seeds=FRESH_SEEDS,
                        main_runs=216, confirmation_runs=18, actual_budget=TOTAL_BUDGET, cap=HARD_CAP,
                        source=SOURCE_PAYLOAD_SHA256, sealed_runtime=_RUNTIME_SHA, source_ppo=SOURCE_PPO,
                        schemas=[MinimalSchema(k).manifest() for k in (2, 3, 4)], fleet=12,
                        trace_sha256=digest(config['trace']), train_horizon=500, eval_horizon=600,
                        reward='源奖励不改；不是corrected StageII', metric='Best完成者ATT为主，平台期为辅，必须并列completion/RPT',
                        information_boundary='只允许已经存在且已承诺的事件，未reveal乘客不可用于输入',
                        auxiliary_pairs=AUX_SAMPLES, auxiliary_shared_norm_ratio=AUX_RATIO,
                        auxiliary_injections_per_rollout=10,
                        evaluation_scope='固定训练trace回放＋新训练seed确认，不声称需求泛化')
        signature = hashlib.sha256(json.dumps(contract, sort_keys=True).encode()).hexdigest()
        old = read_json(root / 'SUITE_PLAN.json')
        if old and old['signature'] != signature:
            raise RuntimeError('合同变更，拒绝混训旧目录')
        if old and old['script_sha256'] != digest(SCRIPT) and not args.allow_code_change:
            raise RuntimeError('代码哈希改变；仅修复实现时可显式--allow-code-change，物理合同不能变')
        save_json(root / 'SUITE_PLAN.json', dict(signature=signature, contract=contract, config=config,
                  script_sha256=digest(SCRIPT), previous_script=old.get('script_sha256') if old else None, time=now()))
        save_json(root / 'TASK_REGISTRY.json', tasks)
        print(f'[预算] 主216run={MAIN_BUDGET:,}；确认18run；总{TOTAL_BUDGET:,}；不改原物理/PPO', flush=True)
        # 先完成前三天最关键的96run，随后补齐；按24run分块穿插评估避免末尾积压。
        if args.phase in ('all', 'train'):
            for offset in range(0, len(tasks), 24):
                block = tasks[offset:offset+24]
                for i, t in enumerate(block, offset+1):
                    print(f'[主训练 {i}/216]', flush=True)
                    full_launch('train', t, root, config); min_aggregate(root, tasks)
                if args.phase == 'all':
                    for t in block:
                        if (root / 'cells' / t['id'] / 'TRAIN_END.json').exists():
                            full_launch('eval', t, root, config); min_aggregate(root, tasks)
        if args.phase in ('all', 'rules', 'eval'):
            for e in ('E0', 'E1'):
                for k in (2, 3, 4):
                    t = dict(id=f'RULES__{e}__K{k}', environment=e, k=k, fleet=12 if e=='E1' else None,
                             method='SINGLE__M0_BASE', variant='M0_BASE', control='LQ', seed=123)
                    full_launch('rules', t, root, config)
        if args.phase in ('all', 'eval'):
            for t in tasks:
                if (root / 'cells' / t['id'] / 'TRAIN_END.json').exists():
                    full_launch('eval', t, root, config)
            # 主run出现失败仍允许其他run继续；未齐全时不得自动挑出有偏的赢家。
            if all((root/'cells'/t['id']/'EVAL_END.json').exists() for t in tasks):
                confirm = choose_confirmation(root, tasks)
                tasks += confirm
                save_json(root / 'TASK_REGISTRY.json', tasks)
                if args.phase == 'all':
                    for i, t in enumerate(confirm, 1):
                        print(f'[独立确认 {i}/18]', flush=True)
                        full_launch('train', t, root, config)
                        if (root/'cells'/t['id']/'TRAIN_END.json').exists():
                            full_launch('eval', t, root, config)
                        min_aggregate(root, tasks)
                else:
                    for t in confirm:
                        if (root/'cells'/t['id']/'TRAIN_END.json').exists():
                            full_launch('eval', t, root, config)
        progress, _, _ = min_aggregate(root, tasks)
        save_json(root / 'SESSION_END.json', dict(phase=args.phase, progress=progress, time=now(),
                  status='COMPLETE' if progress['evaluated']==234 and not progress['failed'] else 'PARTIAL_OR_FAILED'))
        save_json(root / 'LAST_TASK.json', read_json(root / 'RUNNING.json', {}))
        save_json(root / 'RUNNING.json', dict(phase='complete' if progress['evaluated']==234 and not progress['failed'] else 'idle_partial',
                  pid=None, task=None, time=now(), note='当前主会话已结束；进度以progress.json为准'))
        full_pack(root)
        print('[结束]', progress, flush=True)
    except KeyboardInterrupt:
        min_aggregate(root, tasks)
        save_json(root / 'SESSION_INTERRUPTED.json', dict(time=now(), note='相同命令--resume恢复；中断cell不删除'))
        raise SystemExit(130)
    finally:
        if read_json(lock, {}).get('pid') == os.getpid():
            lock.unlink()


if __name__ == '__main__':
    min_main()
